import { readFile, writeFile, mkdir } from "fs/promises";
import path from "path";
import type { Book } from "./types";

const DATA_DIR = path.join(process.cwd(), "data");
const DATA_FILE = path.join(DATA_DIR, "books.json");

async function ensureDataFile(): Promise<void> {
  await mkdir(DATA_DIR, { recursive: true });
  try {
    await readFile(DATA_FILE, "utf-8");
  } catch {
    await writeFile(DATA_FILE, "[]", "utf-8");
  }
}

export async function getBooks(): Promise<Book[]> {
  await ensureDataFile();
  const raw = await readFile(DATA_FILE, "utf-8");
  return JSON.parse(raw) as Book[];
}

async function saveBooks(books: Book[]): Promise<void> {
  await writeFile(DATA_FILE, JSON.stringify(books, null, 2) + "\n", "utf-8");
}

export async function getBook(id: string): Promise<Book | undefined> {
  const books = await getBooks();
  return books.find((b) => b.id === id);
}

export async function addBook(
  title: string,
  author: string,
  notes: string
): Promise<Book> {
  const books = await getBooks();
  const book: Book = {
    id: crypto.randomUUID(),
    title: title.trim(),
    author: author.trim(),
    notes: notes.trim(),
    status: "reading",
    createdAt: new Date().toISOString(),
    finishedAt: null,
  };
  books.unshift(book);
  await saveBooks(books);
  return book;
}

export async function markBookFinished(id: string): Promise<Book | undefined> {
  const books = await getBooks();
  const index = books.findIndex((b) => b.id === id);
  if (index === -1) return undefined;

  const book = books[index];
  if (book.status === "finished") return book;

  books[index] = {
    ...book,
    status: "finished",
    finishedAt: new Date().toISOString(),
  };
  await saveBooks(books);
  return books[index];
}

export async function updateBookNotes(
  id: string,
  notes: string
): Promise<Book | undefined> {
  const books = await getBooks();
  const index = books.findIndex((b) => b.id === id);
  if (index === -1) return undefined;

  books[index] = { ...books[index], notes: notes.trim() };
  await saveBooks(books);
  return books[index];
}

