"use server";

import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { addBook, markBookFinished, updateBookNotes } from "@/lib/books";

export async function addBookAction(formData: FormData) {
  const title = formData.get("title");
  const author = formData.get("author");
  const notes = formData.get("notes");

  if (typeof title !== "string" || !title.trim()) {
    return { error: "Title is required." };
  }
  if (typeof author !== "string" || !author.trim()) {
    return { error: "Author is required." };
  }

  await addBook(
    title,
    author,
    typeof notes === "string" ? notes : ""
  );
  revalidatePath("/");
}

export async function markFinishedAction(formData: FormData) {
  const id = formData.get("id");
  if (typeof id !== "string") return;

  await markBookFinished(id);
  revalidatePath("/");
  revalidatePath(`/books/${id}`);
}

export async function updateNotesAction(formData: FormData) {
  const id = formData.get("id");
  const notes = formData.get("notes");

  if (typeof id !== "string") return;
  if (typeof notes !== "string") return;

  await updateBookNotes(id, notes);
  revalidatePath(`/books/${id}`);
  revalidatePath("/");
  redirect(`/books/${id}`);
}

