import Link from "next/link";
import { notFound } from "next/navigation";
import type { Metadata } from "next";
import { getBook } from "@/lib/books";

type Props = {
  params: Promise<{ id: string }>;
};

export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const { id } = await params;
  const book = await getBook(id);
  if (!book) return { title: "Book not found" };
  return {
    title: `${book.title} — My Books`,
    description: `Notes on ${book.title} by ${book.author}`,
  };
}

export default async function BookPage({ params }: Props) {
  const { id } = await params;
  const book = await getBook(id);

  if (!book) {
    notFound();
  }

  return (
    <>
      <Link href="/" className="back-link">
        ← All books
      </Link>

      <div className="detail-header">
        <h1>{book.title}</h1>
        <div className="book-author">{book.author}</div>
        <span className={`badge ${book.status}`}>
          {book.status === "finished" ? "Finished" : "Reading"}
        </span>
      </div>

      <section className="card notes-section">
        <h2>Notes</h2>
        {book.notes ? (
          <div className="notes-content">{book.notes}</div>
        ) : (
          <p className="notes-empty">No notes yet.</p>
        )}
      </section>

      <p className="share-hint">
        Share this page — anyone with the link can view this book.
      </p>
    </>
  );
}

